{
  "arguments": [
    {
      "claim": "The destruction of the Old Bridge of Mostar was extensive destruction of property not justified by military necessity, constituting a war crime under the Rome Statute.",
      "reasoning": "The bridge was a civilian object and a historic monument, not a military objective. The HVO’s stated purpose was to sap the morale of the Muslim population, not to achieve a concrete military advantage. The alleged advantage of cutting ABiH supply lines was speculative and did not outweigh the extensive loss of cultural property. Accordingly, the act fits the definition of \"extensive destruction and appropriation of property, not justified by military necessity and carried out unlawfully and wantonly\" in art.8(2)(a)(iv) of the Rome Statute.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8(2)(a)(iv)",
          "quoted_text": "Extensive destruction and appropriation of property, not justified by military necessity and carried out unlawfully and wantonly;"
        }
      ]
    },
    {
      "claim": "The attack on the Old Bridge was disproportionate because the anticipated military advantage was not concrete enough to justify the extensive damage to a cultural monument.",
      "reasoning": "Art.8(2)(b)(iv) of the Rome Statute prohibits attacks that cause damage \"clearly excessive in relation to the concrete and direct overall military advantage anticipated.\" The HVO’s claim that the bridge’s destruction would cut off ABiH supply routes was not demonstrated; the bridge’s primary function was civilian transit and cultural heritage. The resulting isolation of residents and psychological impact far exceeded any marginal tactical benefit, rendering the attack disproportionate.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8(2)(b)(iv)",
          "quoted_text": "Intentionally launching an attack in the knowledge that such attack will cause incidental loss of life or injury to civilians or damage to civilian objects or widespread, long-term and severe damage to the natural environment which would be clearly excessive in relation to the concrete and direct overall military advantage anticipated;"
        }
      ]
    },
    {
      "claim": "The Old Bridge, as a historic monument, was protected from attacks under the Additional Protocol II to the Geneva Conventions, making its intentional destruction a prohibited act of hostility.",
      "reasoning": "Article 16 of Additional Protocol II expressly forbids \"any acts of hostility directed against historic monuments, works of art or places of worship which constitute the cultural or spiritual heritage of peoples.\" The Old Bridge, a sixteenth‑century structure and a symbol of Mostar’s cultural heritage, falls squarely within this protection. The HVO’s deliberate targeting of the bridge for morale‑breaking purposes therefore violated this provision.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "ap_ii",
          "article": "16",
          "quoted_text": "Without prejudice to the provisions of the Hague Convention for the Protection of Cultural Property in the Event of Armed Conflict of 14 May 1954, it is prohibited to commit any acts of hostility directed against historic monuments, works of art or places of worship which constitute the cultural or spiritual heritage of peoples, and to use them in support of the military effort."
        }
      ]
    }
  ]
}

